const raw = $json.data || '';

const [resultsPart = '', metadataPart = ''] = raw.split(/\r?\n\r?\nMetadata\r?\n/);

const cleanResultsPart = resultsPart.replace(/^Results\r?\n/, '').trim();
const metadataCsv = metadataPart.trim();

function parseCsvLine(line) {
  const values = [];
  let current = '';
  let inQuotes = false;

  for (let i = 0; i < line.length; i++) {
    const char = line[i];
    const next = line[i + 1];

    if (char === '"' && inQuotes && next === '"') {
      current += '"';
      i++;
    } else if (char === '"') {
      inQuotes = !inQuotes;
    } else if (char === ',' && !inQuotes) {
      values.push(current);
      current = '';
    } else {
      current += char;
    }
  }

  values.push(current);
  return values;
}

function parseCsvBlock(csv) {
  const lines = csv
    .split(/\r?\n/)
    .map((line) => line.trim())
    .filter(Boolean);

  if (lines.length < 2) return [];

  const headers = parseCsvLine(lines[0]);

  return lines.slice(1).map((line) => {
    const values = parseCsvLine(line);
    return Object.fromEntries(headers.map((header, i) => [header, values[i] || '']));
  });
}

const results = parseCsvBlock(cleanResultsPart);
const metadata = parseCsvBlock(metadataCsv)[0] || {};

return [
  {
    json: {
      result_count: results.length,
      results,
      metadata,
    },
  },
];

const email = $input.first().json.Email;

if (email === 0 || email === '0' || !email) {
  return [{ json: { code: 0 } }];
}

const code = String(email).match(/\+([^.]+)\./)?.[1] ?? 0;

return [{ json: { code } }];

